-- PREPARED ONLY. Approved dealer terms amendments; no invented bank movement.
begin;
alter table payments add column obligation_replaced boolean not null default false;
create table uc_consignment_settlement_adjustments(id uuid primary key default gen_random_uuid(),car_id text not null references uc_consignment_cases(car_id),actor_id text not null references garage_building_staff(id),request_id text not null,expected_revision text not null,reason text not null check(length(reason) between 5 and 1000),agreement_document_id uuid not null unique references uc_consignment_documents(id),before_settlement jsonb not null,after_settlement jsonb not null,payable_cents bigint not null check(payable_cents>=0),receivable_cents bigint not null check(receivable_cents>=0),journal_id text references journal_entries(id) deferrable initially deferred,payload jsonb not null,transaction_id bigint not null default txid_current(),created_at timestamptz not null default clock_timestamp(),unique(actor_id,request_id),foreign key(actor_id,request_id) references uc_consignment_commands(actor_id,request_id) deferrable initially deferred);
create table uc_consignment_obligation_replacements(payment_id text primary key references payments(id),adjustment_id uuid not null references uc_consignment_settlement_adjustments(id),before_payment jsonb not null,after_payment jsonb not null,transaction_id bigint not null default txid_current());
create table uc_consignment_adjustment_obligations(payment_id text primary key references payments(id),adjustment_id uuid not null references uc_consignment_settlement_adjustments(id),car_id text not null references uc_consignment_cases(car_id));
do $$ declare t text;begin foreach t in array array['uc_consignment_settlement_adjustments','uc_consignment_obligation_replacements','uc_consignment_adjustment_obligations'] loop execute format('alter table %I enable row level security',t);execute format('revoke all on %I from public,anon,authenticated,service_role',t);execute format('create trigger %I before update or delete on %I for each row execute function uc_investor_immutable()',t||'_fixed',t);execute format('create trigger %I before truncate on %I execute function uc_investor_immutable()',t||'_no_truncate',t);end loop;end $$;
create or replace function uc_consignment_replacement_allowed(p_before jsonb,p_after jsonb) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select p_before-'obligation_replaced'=p_after-'obligation_replaced' and p_before->'obligation_replaced'='false'::jsonb and p_after->'obligation_replaced'='true'::jsonb and exists(select 1 from uc_consignment_obligation_replacements x where x.payment_id=p_before->>'id' and x.transaction_id=txid_current() and x.before_payment=p_before and x.after_payment=p_after)
$$;
create function uc_consignment_replacement_guard() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin
 if tg_op='UPDATE' and (old.bank_name,old.account_number,old.account_holder) is distinct from (new.bank_name,new.account_number,new.account_holder) and exists(select 1 from uc_consignment_adjustment_obligations where payment_id=old.id) then raise exception 'IMMUTABLE_DEALER_BANK';end if;
 if tg_op='INSERT' and new.obligation_replaced or tg_op='UPDATE' and old.obligation_replaced is distinct from new.obligation_replaced and not uc_consignment_replacement_allowed(to_jsonb(old),to_jsonb(new)) then raise exception 'USE_SETTLEMENT_ADJUSTMENT';end if;return new;end $$;
create trigger uc_consignment_obligation_flag before insert or update on payments for each row execute function uc_consignment_replacement_guard();
alter function uc_consignment_receipt_allowed(text,text) rename to uc_consignment_receipt_before_adjustments;
create function uc_consignment_receipt_allowed(p_car text,p_payment text default null) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select uc_consignment_receipt_before_adjustments(p_car,p_payment) or exists(select 1 from uc_consignment_adjustment_obligations x join payments p on p.id=x.payment_id where x.car_id=p_car and p.id=p_payment and p.type='consignment_collection' and not p.obligation_replaced)
$$;
create function uc_consignment_adjustment_plan(p_car text,p_data jsonb) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare k uc_consignment_cases;last_adjust uc_consignment_settlement_adjustments;previous jsonb;next jsonb;bp integer;fixed bigint;cost bigint;net bigint;share bigint;balance bigint;company bigint;paid bigint;collected bigint;open_ap bigint;open_ar bigint;owed bigint;source jsonb;begin
 select * into k from uc_consignment_cases where car_id=p_car;if k.approved_at is null then raise exception 'APPROVED_SETTLEMENT_REQUIRED';end if;
 select * into last_adjust from uc_consignment_settlement_adjustments where car_id=p_car order by created_at desc,id desc limit 1;
 previous:=coalesce(last_adjust.after_settlement,k.settlement||jsonb_build_object('dealerBasisPoints',k.dealer_basis_points,'fixedCents',k.fixed_cents));bp:=coalesce((previous->>'dealerBasisPoints')::integer,k.dealer_basis_points);fixed:=coalesce((previous->>'fixedCents')::bigint,k.fixed_cents);
 if k.terms='profit_split' then if p_data?'fixedAmountCents' or jsonb_typeof(p_data->'dealerBasisPoints') is distinct from 'number' or coalesce(p_data->>'dealerBasisPoints','')!~'^\d{1,5}$' or (p_data->>'dealerBasisPoints')::integer>10000 then raise exception 'CONSIGNMENT_PERCENT_REQUIRED';end if;bp:=(p_data->>'dealerBasisPoints')::integer;
 else if p_data?'dealerBasisPoints' or jsonb_typeof(p_data->'fixedAmountCents') is distinct from 'number' or coalesce(p_data->>'fixedAmountCents','')!~'^[1-9][0-9]{0,11}$' then raise exception 'INVALID';end if;fixed:=(p_data->>'fixedAmountCents')::bigint;end if;
 cost:=(previous->>'costCents')::bigint;net:=k.revenue_cents-k.capital_cents-cost;share:=case when k.terms='profit_split' and net>0 then round(net::numeric*bp/10000)::bigint else 0 end;
 balance:=case when k.terms='fixed_amount' then fixed else k.capital_cents+share-greatest(0,-net) end-k.lender_cents;company:=case when k.terms='fixed_amount' then k.revenue_cents-cost-fixed else greatest(0,net)-share end;
 next:=previous||jsonb_build_object('dealerBasisPoints',bp,'fixedCents',fixed,'dealerProfitCents',share,'dealerLossCents',case when k.terms='profit_split' then greatest(0,-net) else 0 end,'dealerBalanceCents',balance,'dealerPayableCents',greatest(0,balance),'dealerOwesCompanyCents',greatest(0,-balance),'companyResultCents',company);
 select coalesce(sum(case when p.type='consignment_payout' then uc_company_paid_cents(p.id) else 0 end),0),coalesce(sum(case when p.type='consignment_collection' then uc_company_paid_cents(p.id) else 0 end),0),coalesce(sum(case when p.type='consignment_payout' and not p.obligation_replaced then greatest(0,uc_commission_cents(to_jsonb(p)->'amount')-uc_company_paid_cents(p.id)) else 0 end),0),coalesce(sum(case when p.type='consignment_collection' and not p.obligation_replaced then greatest(0,uc_commission_cents(to_jsonb(p)->'amount')-uc_company_paid_cents(p.id)) else 0 end),0) into paid,collected,open_ap,open_ar from payments p where p.id in(k.dealer_payment_id,k.recovery_payment_id) or exists(select 1 from uc_consignment_adjustment_obligations x where x.payment_id=p.id and x.car_id=p_car);
 if open_ap-open_ar<>(previous->>'dealerBalanceCents')::bigint-paid+collected then raise exception 'DEALER_HISTORY_REVIEW_REQUIRED';end if;
 source:=jsonb_build_object('case',to_jsonb(k),'car',(select to_jsonb(c) from cars c where c.id=p_car),'adjustment',to_jsonb(last_adjust),'payments',(select jsonb_agg(to_jsonb(p)||jsonb_build_object('actualPaidCents',uc_company_paid_cents(p.id)) order by p.id) from payments p where p.car_id=p_car),'documents',(select jsonb_agg(to_jsonb(d) order by d.id) from uc_consignment_documents d where d.car_id=p_car));owed:=balance-paid+collected;
 return jsonb_build_object('carId',p_car,'sourceRevision',md5(source::text),'before',previous,'after',next,'paidToDealerCents',paid,'receivedFromDealerCents',collected,'oldPayableCents',open_ap,'oldReceivableCents',open_ar,'payableCents',greatest(0,owed),'receivableCents',greatest(0,-owed));
end $$;
alter function uc_consignment_view(text) rename to uc_consignment_view_before_adjustments;
create function uc_consignment_view(p_car text) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare result jsonb;latest uc_consignment_settlement_adjustments;begin
 result:=uc_consignment_view_before_adjustments(p_car);select * into latest from uc_consignment_settlement_adjustments where car_id=p_car order by created_at desc,id desc limit 1;
 if latest.id is not null then result:=result||jsonb_build_object('originalSettlement',result->'case'->'settlement','case',(result->'case')||jsonb_build_object('settlement',latest.after_settlement,'dealer_basis_points',latest.after_settlement->'dealerBasisPoints','fixed_cents',latest.after_settlement->'fixedCents'));end if;
 return result||jsonb_build_object('settlementAdjustments',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('actorName',(select name from garage_building_staff where id=a.actor_id)) order by a.created_at,a.id) from uc_consignment_settlement_adjustments a where a.car_id=p_car),'[]'::jsonb));
end $$;
alter function uc_consignment_finance(text,text,jsonb) rename to uc_consignment_finance_before_adjustments;
create function uc_consignment_finance(p_actor text,p_action text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare actor garage_building_staff;plan jsonb;k uc_consignment_cases;cmd uc_consignment_commands;p payments;cid text;req text;agreement uc_consignment_documents;a_id uuid:=gen_random_uuid();ctx text;pid text;jid text;lines jsonb:='[]'::jsonb;leg jsonb;old_company bigint;new_company bigint;payable bigint;receivable bigint;begin
 if p_action not in ('preview_adjustment','adjust_settlement') then return uc_consignment_finance_before_adjustments(p_actor,p_action,p_data);end if;
 select * into actor from garage_building_staff where id=p_actor for share;if actor.id is null or not coalesce(actor.enabled and actor.registration_status='active' and actor.role='director' and actor.business_access in ('used_car','both'),false) then raise exception 'NOT_ALLOWED';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data) x where x<>all(array['carId','dealerBasisPoints','fixedAmountCents','agreementDocumentId','reason','expectedRevision','requestId'])) then raise exception 'INVALID';end if;
 cid:=p_data->>'carId';if coalesce(cid,'')!~'^[A-Za-z0-9_-]{1,100}$' then raise exception 'INVALID';end if;
 if p_action='preview_adjustment' then return jsonb_build_object('preview',uc_consignment_adjustment_plan(cid,p_data));end if;
 req:=p_data->>'requestId';if coalesce(req,'')!~'^[A-Za-z0-9_-]{16,80}$' or jsonb_typeof(p_data->'reason') is distinct from 'string' or length(trim(p_data->>'reason')) not between 5 and 1000 or p_data->>'reason'~'[[:cntrl:]]' then raise exception 'INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended('company-trade-in-funding',0));perform pg_advisory_xact_lock(hashtextextended('consignment:'||p_actor||':'||req,0));
 select * into cmd from uc_consignment_commands where actor_id=p_actor and request_id=req;if found then if cmd.payload is distinct from jsonb_build_object('action',p_action,'data',p_data) then raise exception 'REQUEST_CHANGED';end if;return uc_consignment_view(cid)||jsonb_build_object('car',(select to_jsonb(c) from cars c where id=cid),'journals',coalesce((select jsonb_agg(to_jsonb(j)) from journal_entries j join uc_consignment_settlement_adjustments x on x.journal_id=j.id where x.actor_id=p_actor and x.request_id=req),'[]'::jsonb));end if;
 perform 1 from cars where id=cid for update;perform 1 from payments where car_id=cid order by id for update;select * into k from uc_consignment_cases where car_id=cid for update;
 plan:=uc_consignment_adjustment_plan(cid,p_data);if plan->>'sourceRevision' is distinct from p_data->>'expectedRevision' then raise exception 'SOURCE_CHANGED';end if;
 if plan->'after'->'dealerBasisPoints' is not distinct from plan->'before'->'dealerBasisPoints' and plan->'after'->'fixedCents' is not distinct from plan->'before'->'fixedCents' then raise exception 'NO_CORRECTION_CHANGE';end if;
 select * into agreement from uc_consignment_documents where id=(p_data->>'agreementDocumentId')::uuid and car_id=cid and confirmed_at is not null and amendment_terms=case when k.terms='profit_split' then jsonb_build_object('dealerBasisPoints',(plan->'after'->>'dealerBasisPoints')::integer) else jsonb_build_object('fixedAmountCents',(plan->'after'->>'fixedCents')::bigint) end and created_at>=coalesce((select max(created_at) from uc_consignment_settlement_adjustments where car_id=cid),k.approved_at) and not exists(select 1 from uc_consignment_settlement_adjustments where agreement_document_id=(p_data->>'agreementDocumentId')::uuid);
 if agreement.id is null then raise exception 'NEW_SETTLEMENT_AGREEMENT_REQUIRED';end if;
 payable:=(plan->>'payableCents')::bigint;receivable:=(plan->>'receivableCents')::bigint;old_company:=(plan->'before'->>'companyResultCents')::bigint;new_company:=(plan->'after'->>'companyResultCents')::bigint;
 for leg in select jsonb_build_object('accountId',a,'debit',d::numeric/100,'credit',c::numeric/100) from (values('acct-ap',(plan->>'oldPayableCents')::bigint,0::bigint),('acct-ap',0::bigint,payable),('acct-consignor-ar',receivable,0::bigint),('acct-consignor-ar',0::bigint,(plan->>'oldReceivableCents')::bigint),('acct-rev-consign',greatest(old_company,0),0::bigint),('acct-rev-consign',0::bigint,greatest(new_company,0)),('acct-exp-consign-loss',greatest(-new_company,0),0::bigint),('acct-exp-consign-loss',0::bigint,greatest(-old_company,0))) v(a,d,c) where d<>0 or c<>0 loop lines:=lines||jsonb_build_array(leg);end loop;
 if plan->'after'->'dealerBalanceCents'=plan->'before'->'dealerBalanceCents' and plan->'after'->'companyResultCents'=plan->'before'->'companyResultCents' then lines:='[]'::jsonb;end if;
 if jsonb_array_length(lines)>0 then jid:='uc:consign-adjustment:'||a_id;end if;
 insert into uc_consignment_settlement_adjustments(id,car_id,actor_id,request_id,expected_revision,reason,agreement_document_id,before_settlement,after_settlement,payable_cents,receivable_cents,journal_id,payload) values(a_id,cid,p_actor,req,p_data->>'expectedRevision',trim(p_data->>'reason'),agreement.id,plan->'before',plan->'after',payable,receivable,jid,p_data);
 ctx:=current_setting('autodream.consignment_write',true);perform set_config('autodream.consignment_write',txid_current()::text||':'||cid,true);
 if jid is not null then
 for p in select * from payments s where not s.obligation_replaced and (s.id in(k.dealer_payment_id,k.recovery_payment_id) or exists(select 1 from uc_consignment_adjustment_obligations x where x.payment_id=s.id and x.car_id=cid)) order by s.id loop
  insert into uc_consignment_obligation_replacements values(p.id,a_id,to_jsonb(p),to_jsonb(p)||jsonb_build_object('obligation_replaced',true),txid_current());update payments set obligation_replaced=true where id=p.id;
 end loop;
 if payable>0 or receivable>0 then
  pid:='consign-adjustment:'||a_id;
  insert into payments(id,car_id,type,status,amount,recipient_type,recipient_id,recipient_name,bank_name,account_number,account_holder,description,created_at) values(pid,cid,case when payable>0 then 'consignment_payout' else 'consignment_collection' end,'pending',greatest(payable,receivable)::numeric/100,'dealer',k.dealer->>'id',k.dealer->>'name',k.dealer->>'bankName',k.dealer->>'accountNumber',k.dealer->>'accountHolder','Revised dealer balance; original payments retained',now());
  insert into uc_consignment_adjustment_obligations values(pid,a_id,cid);
 end if;
 if jid is not null then perform uc_post_journal('consign-adjustment:'||a_id,(now() at time zone 'Asia/Kuala_Lumpur')::date,'Approved consignment terms adjustment; no bank movement',cid,p_actor,lines);end if;
 if payable>0 then insert into uc_consignment_bill_sources values(pid,cid,jid,payable);end if;
 end if;
 update cars set consignment_settlement=(plan->'after')-'bills'-'sourceRevision',consignment=jsonb_set(consignment,case when k.terms='profit_split' then '{splitPercent}'::text[] else '{fixedAmount}'::text[] end,to_jsonb(case when k.terms='profit_split' then (plan->'after'->>'dealerBasisPoints')::numeric/100 else (plan->'after'->>'fixedCents')::numeric/100 end)) where id=cid;
 insert into uc_consignment_commands values(p_actor,req,jsonb_build_object('action',p_action,'data',p_data),cid,now());perform set_config('autodream.consignment_write',coalesce(ctx,''),true);
 return uc_consignment_view(cid)||jsonb_build_object('car',(select to_jsonb(c) from cars c where id=cid),'journals',coalesce((select jsonb_agg(to_jsonb(j)) from journal_entries j where id=jid),'[]'::jsonb));
end $$;
alter function uc_company_cash_position() rename to uc_company_position_before_adjustments;
create function uc_company_cash_position() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$ declare result jsonb;reserved bigint;begin result:=uc_company_position_before_adjustments();select coalesce(sum(greatest(0,uc_commission_cents(to_jsonb(p)->'amount')-uc_company_paid_cents(p.id))),0) into reserved from uc_consignment_adjustment_obligations x join payments p on p.id=x.payment_id where p.type='consignment_payout' and p.status='pending' and not p.obligation_replaced;return result||jsonb_build_object('unpaidCompanyCents',(result->>'unpaidCompanyCents')::bigint+reserved,'availableCents',(result->>'availableCents')::bigint-reserved);end $$;
revoke all on function uc_consignment_replacement_allowed(jsonb,jsonb),uc_consignment_replacement_guard(),uc_consignment_receipt_before_adjustments(text,text),uc_consignment_receipt_allowed(text,text),uc_consignment_adjustment_plan(text,jsonb),uc_consignment_view_before_adjustments(text),uc_consignment_view(text),uc_consignment_finance_before_adjustments(text,text,jsonb),uc_consignment_finance(text,text,jsonb),uc_company_position_before_adjustments(),uc_company_cash_position() from public,anon,authenticated,service_role;
grant execute on function uc_consignment_finance(text,text,jsonb) to service_role;
commit;
